import {test,expect} from '@playwright/test';
const list=(page:any)=>page.getByRole('list',{name:'报名记录',exact:true});
const fill=async(page:any,name:string,email:string)=>{await page.getByLabel('姓名',{exact:true}).fill(name);await page.getByLabel('邮箱',{exact:true}).fill(email)};
const submit=async(page:any)=>{const button=page.getByRole('button',{name:'保存报名',exact:true});if(await button.isEnabled())await button.click()};
test('独立：必填和邮箱校验',async({page})=>{await page.goto('/');await submit(page);await expect(list(page).getByRole('listitem')).toHaveCount(0);await fill(page,'甲','not-an-email');await submit(page);await expect(list(page).getByRole('listitem')).toHaveCount(0);await fill(page,'','test@example.com');await submit(page);await expect(list(page).getByRole('listitem')).toHaveCount(0)});
test('独立：正确保存后清空表单',async({page})=>{await page.goto('/');await fill(page,'甲','a@example.com');await submit(page);await expect(list(page).getByRole('listitem')).toHaveCount(1);await expect(list(page)).toContainText('甲');await expect(list(page)).toContainText('a@example.com');await expect(page.getByLabel('姓名',{exact:true})).toHaveValue('');await expect(page.getByLabel('邮箱',{exact:true})).toHaveValue('')});
test('独立：刷新后持久化且可继续新增',async({page})=>{await page.goto('/');await fill(page,'甲','a@example.com');await submit(page);await page.reload();await expect(list(page).getByRole('listitem')).toHaveCount(1);await expect(list(page)).toContainText('a@example.com');await fill(page,'乙','b@example.com');await submit(page);await page.reload();await expect(list(page).getByRole('listitem')).toHaveCount(2);await expect(list(page)).toContainText('b@example.com')});
test('独立：手机宽度',async({page})=>{await page.setViewportSize({width:390,height:844});await page.goto('/');await expect(page.getByLabel('姓名',{exact:true})).toBeVisible();expect(await page.evaluate(()=>document.documentElement.scrollWidth<=innerWidth+1)).toBe(true)});
